presets.css:
.chat-thread {
  --chat-bg: #EEEEEE;   /* ★ 改这个数，全聊天背景跟着变 */
}

.chat-thread,
.chat-thread-bg {
  background: var(--chat-bg) !important;
}

/* ============================================================
   Puff · 顶栏（纯白底 · 灰分割线 · 保留功能 · 右侧文字）
   ============================================================ */

.chat-thread {
  --head-bg: #ffffff;
  --head-line: rgba(0, 0, 0, 0.08);
  --head-text: #14161c;
  --head-sub: rgba(0, 0, 0, 0.48);
  --head-icon: rgba(0, 0, 0, 0.62);
  --head-hover: rgba(0, 0, 0, 0.05);
  --head-h: 52px;
}

html[data-theme="dark"] .chat-thread {
  --head-bg: #1a1c22;
  --head-line: rgba(255, 255, 255, 0.09);
  --head-text: #e8eaf0;
  --head-sub: rgba(255, 255, 255, 0.52);
  --head-icon: rgba(255, 255, 255, 0.68);
  --head-hover: rgba(255, 255, 255, 0.06);
}

/* ========== 外壳 ========== */
.chat-thread-top {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  z-index: 20;
  padding: 0;
  pointer-events: none;
}

.chat-thread-pill,
.chat-thread-pill-detail {
  pointer-events: auto;
  position: relative;
  display: flex;
  align-items: center;

  height: var(--head-h);
  padding: 0 12px;

  background: var(--head-bg);
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
  border: 0;
  border-radius: 0;
  box-shadow: none;
  border-bottom: 1px solid var(--head-line);
  color: var(--head-text);
}

/* ========== 顶栏返回图标替换 ========== */

.chat-thread {
  --back-icon: url("https://img.remit.ee/i/ixWyJqNEwRJi");
  --back-icon-size: 22px;   /* 图标显示大小，自己调 */
}

/* 返回按钮：藏掉原字符，铺图 */
.chat-thread-pill .chat-back,
.chat-thread-pill-detail .chat-back,
.chat-back-wrap {
  font-size: 0 !important;
  color: transparent !important;
  -webkit-text-fill-color: transparent !important;
  text-shadow: none !important;
  text-indent: -9999px;        /* 兜底：把字符物理推走 */
  overflow: hidden !important;

  display: grid !important;
  place-items: center !important;
  background: transparent !important;
}

/* 用 ::before 铺图标 */
.chat-thread-pill .chat-back::before,
.chat-thread-pill-detail .chat-back::before,
.chat-back-wrap::before {
  content: "" !important;
  display: block !important;

  width: var(--back-icon-size) !important;
  height: var(--back-icon-size) !important;

  background: var(--back-icon) center / contain no-repeat !important;
  text-indent: 0;
  z-index: 1;
}

/* 深色模式不用换图，图标本身带颜色 */

.chat-thread-pill .chat-back:hover,
.chat-thread-pill-detail .chat-back:hover {
  background: var(--head-hover);
  color: var(--head-text);
}

.chat-thread-pill .chat-back::before,
.chat-thread-pill-detail .chat-back::before,
.chat-back-wrap::before {
  transform: translateY(9px) !important;   /* ★ 正数往下，负数往上 */
}

/* ========== 中间标题（绝对居中，字号加大） ========== */
.chat-thread-center {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  max-width: calc(100% - 190px);
  text-align: center;
  line-height: 1.25;
  pointer-events: none;
}
.chat-thread-center h2 {
  margin: 0;
  font-size: 20px;          /* ★ 标题名字大小 */
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--head-text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.chat-thread-center span {
  display: block;
  margin-top: 3px;
  font-size: 12px;          /* ★ 备注文字调大（原 10.5px） */
  color: var(--head-sub);
}

/* ========== 右侧心声（爱心功能保留，改成文字「心声」） ========== */
.chat-thread-head-xinsheng {
  position: absolute;
  right: 68px;              /* 排在设置左边 */
  top: 50%;
  transform: translateY(-50%);
  width: auto;
  height: auto;
  padding: 6px 6px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  cursor: pointer;
  font-size: 0 !important;  /* 隐藏原来的爱心图标 */
  color: transparent !important;
  line-height: 1;
  z-index: 2;
  transition: background 0.16s ease;
}
.chat-thread-head-xinsheng:hover {
  background: var(--head-hover);
}


/* ========== 右侧更多（设置功能保留，改成文字「设置」） ========== */
.chat-thread-head-more {
  position: absolute;
  right: 12px;
  top: 50%;
  transform: translateY(-50%);
  width: auto;
  height: auto;
  padding: 6px 6px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  cursor: pointer;
  font-size: 0 !important;  /* 隐藏原来的三点图标 */
  color: transparent !important;
  line-height: 1;
  z-index: 2;
  transition: background 0.16s ease;
}
.chat-thread-head-more:hover {
  background: var(--head-hover);
}
.chat-thread-head-more::after {
  content: "设置";
  font-size: 20px;        /* ★ 设置字号调大（原 14px） */
  font-weight: 500;
  color: var(--head-text);
}



/* ========== L. 输入栏（完整版） ========== */

/* ---- 变量 ---- */
.chat-thread {
  /* 底栏 */
  --compose-bg: #ffffff;
  --compose-pad-x: 14px;
  --compose-pad-y: 8px;

  /* 输入框：浅灰胶囊 */
  --compose-input-bg: #f2f3f5;
  --compose-input-fg: #14161c;
  --compose-input-ph: rgba(0, 0, 0, 0.35);
  --compose-input-h: 38px;

  /* 图标 URL */
  --icon-plus:  url("https://img.remit.ee/i/UJjjX1u3q3Un");
  --icon-voice: url("https://img.remit.ee/i/YFITRQXEjhow");
  --icon-reply: url("https://img.remit.ee/i/1phA4nFWB7LU");
  --icon-third: url("https://img.remit.ee/i/6nnZh3TnXb69");
  --icon-size: var(--compose-input-h);
}

html[data-theme="dark"] .chat-thread {
  --compose-bg: #1a1c22;
  --compose-input-bg: #2a2c32;
  --compose-input-fg: #e8eaf0;
  --compose-input-ph: rgba(255, 255, 255, 0.38);
}

/* ---- 外层：通栏贴底 ---- */
.chat-compose {
  background: var(--compose-bg) !important;
  border: 0 !important;
  border-radius: 0 !important;
  padding: var(--compose-pad-y) var(--compose-pad-x) calc(var(--compose-pad-y) + env(safe-area-inset-bottom, 0px)) !important;
}

/* ---- 底栏本体 ---- */
.chat-compose-bar {
  display: flex !important;
  align-items: center !important;
  gap: 8px !important;
  height: auto !important;
  padding: 0 !important;
  background: var(--compose-bg) !important;
  border: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
}

/* ---- 输入框：浅灰胶囊 ---- */
.chat-compose-input {
  flex: 1 1 auto !important;
  min-width: 0 !important;
  height: var(--compose-input-h) !important;
  padding: 0 16px !important;
  box-sizing: border-box !important;
  margin: 0 !important;
  background: var(--compose-input-bg) !important;
  color: var(--compose-input-fg) !important;
  border: 0 !important;
  border-radius: 999px !important;
  box-shadow: none !important;
  outline: 0 !important;
  font-size: 14px !important;
  line-height: var(--compose-input-h) !important;
  -webkit-appearance: none !important;
  appearance: none !important;
}
.chat-compose-input::placeholder {
  color: var(--compose-input-ph) !important;
}

/* ---- 所有图标按钮统一规格 ---- */
.chat-compose-plus,
.chat-compose-icon {
  flex: 0 0 var(--compose-input-h) !important;
  width: var(--compose-input-h) !important;
  height: var(--compose-input-h) !important;

  display: grid !important;
  place-items: center !important;

  background: transparent !important;
  border: 0 !important;
  border-radius: 50% !important;
  box-shadow: none !important;

  font-size: 0 !important;
  color: transparent !important;
  -webkit-text-fill-color: transparent !important;
  text-shadow: none !important;
  overflow: hidden !important;
  cursor: pointer;

  /* 不管 ready 不 ready，都强制显示 */
  opacity: 1 !important;
  visibility: visible !important;
  transform: none !important;
}

/* 伪元素容器 */
.chat-compose-plus::before,
.chat-compose-icon::before {
  content: "" !important;
  display: block !important;
  width: var(--icon-size) !important;
  height: var(--icon-size) !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-size: contain !important;
  background-image: none !important;
}

/* ---- 左边加号 ---- */
.chat-compose-plus::before {
  background-image: var(--icon-plus) !important;
}

/* ---- 右边图标：按位置铺图 ---- */
/* 倒数第 1 个 icon = 语音 */
.chat-compose-icon:nth-last-of-type(1)::before {
  background-image: var(--icon-voice) !important;
}

/* 倒数第 2 个 icon = 回复 */
.chat-compose-icon:nth-last-of-type(2)::before {
  background-image: var(--icon-reply) !important;
}

/* ---- 第三个图标：伪元素挂在底栏最右 ---- */
.chat-compose-bar::after {
  content: "" !important;
  flex: 0 0 var(--compose-input-h) !important;
  width: var(--compose-input-h) !important;
  height: var(--compose-input-h) !important;
  background: var(--icon-third) center / var(--icon-size) no-repeat !important;
  border-radius: 50% !important;
}

/* ========== 我方气泡 ========== */
.chat-thread {
  --dress-bubble-me-bg: #40A3FF;
  --dress-bubble-me-fg: #ffffff;
  --dress-bubble-me-border: none;
  --dress-bubble-me-shadow: 0 2px 10px rgba(64, 163, 255, 0.);
  --dress-bubble-me-radius: 12px;

  /* ★ 对方气泡 */
  --dress-bubble-them-bg: #ffffff;
  --dress-bubble-them-fg: var(--ink);
  --dress-bubble-them-border: none;
  --dress-bubble-them-shadow: 0 2px 10px rgba(0, 0, 0, 0.0);
  --dress-bubble-them-radius: 12px;
}

/* 我方：逐层解除裁切 */
.chat-msg.is-me .chat-msg-body,
.chat-msg.is-me .chat-longpress-host,
.chat-msg.is-me .chat-swipe-host,
.chat-msg.is-me .chat-swipe-content,
.chat-msg.is-me .chat-bubble-primary,
.chat-msg.is-me .chat-bubble {
  overflow: visible !important;
}

/* 我方：小尾巴 */
.chat-msg.is-me .chat-bubble::after {
  content: "";
  display: block;
  position: absolute;
  right: -6px;
  top: 6px;
  width: 16px;
  height: 20px;
  background: url('https://img.remit.ee/i/D82aR8E1dYLC') no-repeat center / contain;
  pointer-events: none;
  z-index: 10;
}

/* ★ 对方：逐层解除裁切 */
.chat-msg.is-them .chat-msg-body,
.chat-msg.is-them .chat-longpress-host,
.chat-msg.is-them .chat-swipe-host,
.chat-msg.is-them .chat-swipe-content,
.chat-msg.is-them .chat-bubble-primary,
.chat-msg.is-them .chat-bubble {
  overflow: visible !important;
}

/* ★ 对方：小尾巴 */
.chat-msg.is-them .chat-bubble::after {
  content: "";
  display: block;
  position: absolute;
  left: -6.8px;
  top: 7px;
  width: 16px;
  height: 20px;
  background: url('https://img.remit.ee/i/PJVqcObdpyUS') no-repeat center / contain;
  pointer-events: none;
  z-index: 10;
}

/* ========== 头像 ========== */
.chat-ava,
.chat-ava-sm {
  width: 40px !important;
  height: 40px !important;
  min-width: 40px !important;
  min-height: 40px !important;
  border-radius: 100px;          /* 微圆角，如需全圆改 50%，方角改 4px */
  object-fit: cover;
  flex-shrink: 0;
}

/* 保证头像包裹容器也保持 40px 不被压缩 */
.chat-ava-wrap {
  width: 40px !important;
  height: 40px !important;
  flex-shrink: 0;
}


/* ========== F. 时间戳移到气泡下方外侧（远离头像那侧） ========== */

/* 把 bubble + time 改为纵向排列 */
.chat-msg.is-me .chat-swipe-content,
.chat-msg.is-them .chat-swipe-content {
  display: flex !important;
  flex-direction: column !important;
}

/* 我方：头像在右 → 时间戳贴气泡左下角 */
.chat-msg.is-me .chat-swipe-content .chat-msg-time {
  align-self: flex-start !important;
  margin-top: -13px !important;
  margin-left: -29px !important;
}

/* 对方：头像在左 → 时间戳贴气泡右下角 */
.chat-msg.is-them .chat-swipe-content .chat-msg-time {
  align-self: flex-end !important;
  margin-top: 3px !important;
  margin-right: -30px !important;
}

.chat-thinking-row {
  margin: 0 !important;
  padding: 0 !important;
  transform: translateY(2px) !important;
  z-index: 2 !important;
  /* ★ 不要写 pointer-events: none，写了就点不动 */
}

.chat-thinking-chip {
  display: inline-block;
  padding: 2px 10px;
  border-radius: 999px;
  font-size: 11px;
  letter-spacing: 0.04em;
  line-height: 1.4;

  background: rgba(255, 255, 255, 0.08);
  color: rgba(0, 0, 0, 0.42);

  border: 0;
  box-shadow: none;
  -webkit-backdrop-filter: blur(10px);
  backdrop-filter: blur(10px);

  cursor: pointer;   /* 视觉上告诉用户能点 */
}

html[data-theme="dark"] .chat-thinking-chip {
  background: rgba(255, 255, 255, 0.08);
  color: rgba(255, 255, 255, 0.45);
}

/* ========== 推演 chip：藏掉原文字，只显 @✩ ========== */
.chat-thinking-chip {
  /* 清掉原来的底和字 */
  background: transparent !important;
  border: 0 !important;
  box-shadow: none !important;
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;

  /* 把原来的文字藏起来 */
  font-size: 0 !important;
  color: transparent !important;
  -webkit-text-fill-color: transparent !important;
  padding: 0 !important;

  position: relative;
  display: inline-block;
  min-width: 20px;
  min-height: 20px;
}

/* @✩ 伪元素 */
.chat-thinking-chip::before {
  content: "@✩";
  display: inline-block;

  font-size: 12px;                  /* ★ 符号大小 */
  line-height: 1;
  letter-spacing: 0.02em;

  color: rgba(0, 0, 0, 0.42);       /* ★ 符号颜色 */
  -webkit-text-fill-color: currentColor;

  transform: translateY(-1px);      /* 微调垂直位置 */
}

html[data-theme="dark"] .chat-thinking-chip::before {
  color: rgba(255, 255, 255, 0.45);
}


.chat-thinking-chip::before {
  content: "@✩";
  display: inline-block;

  font-size: 12px;
  line-height: 1;
  letter-spacing: 0.02em;

  color: rgba(0, 0, 0, 0.42);
  -webkit-text-fill-color: currentColor;

  transform: translate(9.5px, 3px);   /* ★ 第一个值是左右，第二个是上下 */
}

/* 藏昵称 */
.chat-msg-name {
  display: none !important;
}

/* ★ 只推对方气泡：transform 不会被 flex 对齐吃掉 */
.chat-msg:not(.is-me) .chat-bubble {
  transform: translateY(17px) !important;
}



/* ★ 先清掉父容器 gap，不然间距会双重叠加 */
.chat-thread-scroll,
.chat-history-fold,
.chat-history-fold-wrap {
  gap: 0 !important;
}

/* 所有消息先归零，避免继承别的间距 */
.chat-msg {
  margin-top: 0 !important;
  margin-bottom: 0 !important;
}

/* ★ AI 消息：下方间距大一点 */
.chat-msg:not(.is-me) {
  margin-bottom: 4px !important;
}

/* ★ 用户消息：下方间距小一点 */
.chat-msg.is-me {
  margin-bottom: 17px !important;
}


/* ========== I. 表情 / 图片（间距 + 尺寸） ========== */

/* 所有消息先归零 */
.chat-msg {
  margin-top: 0 !important;
  margin-bottom: 0 !important;
}

/* ===== 表情包消息 ===== */
.chat-msg.has-sticker {
  margin-top: 0px !important;
  margin-bottom: 5px !important;
}

.chat-bubble-sticker {
  width: 85px !important;        /* ★ 表情包 */
  height: 85px !important;
  object-fit: contain !important;
  padding: 0 !important;
  margin: 0 !important;
}

/* ===== 图片消息 ===== */
.chat-msg.has-image {
  margin-top: 8px !important;
  margin-bottom: 8px !important;
}

.puff-photo {
  width: 90px !important;        /* ★ 图片 */
  height: auto !important;
  object-fit: cover !important;
  border-radius: 8px !important;
  padding: 0 !important;
  margin: 0 !important;
}

/* 兜底：清掉内部包裹层 padding */
.chat-msg.has-sticker .chat-msg-body,
.chat-msg.has-image .chat-msg-body {
  padding-top: 0 !important;
  padding-bottom: 0 !important;
  gap: 0 !important;
}
/* 表情包消息：藏掉时间戳 */
.chat-msg.has-sticker .chat-msg-time,
.chat-msg.has-sticker .chat-msg-timestamp {
  display: none !important;
}


/* 消息行：自适应高度 + 正常间距 */
.chat-msg {
  height: auto !important;
  min-height: 0 !important;
  overflow: visible !important;
  margin-bottom: 3px !important;
}

/* 消息体：不压高度 */
.chat-msg-body {
  height: auto !important;
  min-height: 0 !important;
  margin-bottom: 0 !important;
  overflow: visible !important;
}

/* 气泡：正常行高，不压扁 */
.chat-bubble {
  height: auto !important;
  min-height: 0 !important;
  line-height: 1.4 !important;
  overflow: visible !important;
}

/* 表情包消息单独收（不影响文字气泡） */
.chat-msg.has-sticker .chat-bubble,
.chat-msg.has-image .chat-bubble {
  line-height: 0 !important;
  padding: 0 !important;
}

/* 带引用的消息：下方多留空间，防止下一条压上来 */
.chat-msg:has(.chat-qq-quote) {
  margin-bottom: 24px !important;
}


/* ========== I. 语音 ========== */

/* AI / 对方语音：白底、无阴影 */
.chat-msg:not(.is-me) .puff-voice-pill {
  background: #ffffff !important;
  color: var(--ink) !important;
  border: 0 !important;
  border-radius: 999px !important;
  box-shadow: none !important;
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
  padding: 9px 16px 9px 12px !important;
  transform: translateY(14px) !important;
}

html[data-theme="dark"] .chat-msg:not(.is-me) .puff-voice-pill {
  background: #2e2e2e !important;
  color: #efefef !important;
}

/* ★ 用户 / 我方语音：#40A3FF 蓝底、白字、无阴影 */
.chat-msg.is-me .puff-voice-pill {
  background: #40A3FF !important;
  color: #ffffff !important;
  border: 0 !important;
  border-radius: 999px !important;
  box-shadow: none !important;
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
  padding: 9px 16px 9px 12px !important;
}

/* 语音内部元素跟随气泡颜色 */
.puff-voice-glyph,
.puff-voice-waves,
.puff-voice-wave {
  color: inherit !important;
}
.puff-voice-dur {
  color: inherit !important;
  opacity: 0.72;
}

/* 语音转文字块下推（AI 这边） */
.chat-msg:not(.is-me) .puff-voice-note,
.chat-msg:not(.is-me) .puff-voice-note-body,
.chat-msg:not(.is-me) .puff-voice-note-tr {
  transform: translateY(14px) !important;
}
/* ========== 语音转文字块 ========== */

/* ★ 宽度随文字变化 + 文字裹在里面 */
.puff-voice-note {
  display: inline-block !important;
  width: fit-content !important;
  max-width: 100% !important;

  padding: 8px 12px !important;      /* 内边距，文字被裹住 */
  margin: 6px 0 0 0 !important;      /* 上方跟语音条留一点距离 */
  box-sizing: border-box !important;

  line-height: 1.5 !important;
  word-break: break-word !important;

  border-radius: 12px !important;
}

/* 文字内容层：跟着块走 */
.puff-voice-note-body {
  display: block !important;
  width: 100% !important;
  padding: 0 !important;
  margin: 0 !important;
  line-height: inherit !important;
}

.puff-voice-note-tr {
  display: block !important;
  width: 100% !important;
  padding: 0 !important;
  margin: 0 !important;
  line-height: inherit !important;
}

/* AI 语音转文字：下推 + 灰底 */
.chat-msg:not(.is-me) .puff-voice-note {
  transform: translateY(14px) !important;
  background: rgba(0, 0, 0, 0.04) !important;
  color: var(--ink) !important;
}

/* 用户语音转文字：下推 + 淡蓝底（跟语音气泡呼应） */
.chat-msg.is-me .puff-voice-note {
  background: rgba(242, 250, 255, 0.75) !important;
  color: var(--ink) !important;
}

html[data-theme="dark"] .chat-msg:not(.is-me) .puff-voice-note {
  background: rgba(255, 255, 255, 0.06) !important;
  color: #efefef !important;
}
html[data-theme="dark"] .chat-msg.is-me .puff-voice-note {
  background: rgba(64, 163, 255, 0.20) !important;
  color: #efefef !important;
}

/* 清掉内部残留的推挤 / 撑高 */
.chat-msg:not(.is-me) .puff-voice-note-body,
.chat-msg:not(.is-me) .puff-voice-note-tr {
  transform: none !important;
}



/* ========== G. 引用 ========== */

.chat-qq-quote {
  /* 去掉左边小竖条 */
  border-left: 0 !important;
  border: 0 !important;

  padding: 6px 10px !important;
  margin-bottom: 6px !important;
  border-radius: 8px !important;
}

/* ★ AI 引用：黑灰色文字 */
.chat-msg:not(.is-me) .chat-qq-quote,
.chat-msg:not(.is-me) .chat-qq-quote-name,
.chat-msg:not(.is-me) .chat-qq-quote-text {
  color: rgba(0, 0, 0, 0.55) !important;
}

/* ★ 用户引用：白灰色文字 */
.chat-msg.is-me .chat-qq-quote,
.chat-msg.is-me .chat-qq-quote-name,
.chat-msg.is-me .chat-qq-quote-text {
  color: rgba(255, 255, 255, 0.75) !important;
}

/* 深色模式 */
html[data-theme="dark"] .chat-msg:not(.is-me) .chat-qq-quote,
html[data-theme="dark"] .chat-msg:not(.is-me) .chat-qq-quote-name,
html[data-theme="dark"] .chat-msg:not(.is-me) .chat-qq-quote-text {
  color: rgba(255, 255, 255, 0.55) !important;
}
html[data-theme="dark"] .chat-msg.is-me .chat-qq-quote,
html[data-theme="dark"] .chat-msg.is-me .chat-qq-quote-name,
html[data-theme="dark"] .chat-msg.is-me .chat-qq-quote-text {
  color: rgba(255, 255, 255, 0.75) !important;
}

/* 名字 / 文字大小 */
.chat-qq-quote-name {
  font-size: 11px !important;
  margin-bottom: 2px !important;
}

.chat-qq-quote-text {
  font-size: 12px !important;
  line-height: 1.4 !important;
}


/* ========== 语音条上下间距 ========== */

/* 语音消息整行的上下间距 */
.chat-msg.has-voice {
  margin-top: 8px !important;
  margin-bottom: 8px !important;
}

/* 语音气泡本体的上下间距（如果上面不够用） */
.chat-msg.has-voice .puff-voice-pill {
  margin-top: 4px !important;
  margin-bottom: 4px !important;
}
